// Mockup rendering for the Design Studio. Artwork for each side arrives as a canvas (trim size, no bleed);
// scenes are composited on canvas with clean vector props (doors, stands, grass) or product photos.
import {PRODUCTS,dimensions,hangerHole,sideViews} from './model.mjs';
import {t} from './i18n.mjs';
export const load=src=>new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(Error('Could not load a mockup image.'));i.src=src;});
const canvas=(w,h)=>{const c=document.createElement('canvas');c.width=Math.round(w);c.height=Math.round(h);return [c,c.getContext('2d')];};
function rr(ctx,x,y,w,h,r){ctx.beginPath();if(r>0)ctx.roundRect(x,y,w,h,r);else ctx.rect(x,y,w,h);}
const fit=(art,maxW,maxH)=>{const a=art.width/art.height,w=Math.min(maxW,maxH*a);return [w,w/a];};
// Tiny deterministic random so grass/texture is identical between renders.
function rng(seed=7){return ()=>((seed=Math.imul(seed^seed>>>15,seed|1)^seed+Math.imul(seed^seed>>>7,seed|61)),((seed^seed>>>14)>>>0)/4294967296);}

/* ---------------- vehicles ---------------- */
const VEHICLES={'vehicle-van':{name:'van',box:[15,195,1500]},'vehicle-pickup':{name:'pickup',box:[12,238,1512]},'vehicle-minivan':{name:'minivan',box:[4,186,1522]}};
export const vehicleAsset=design=>'/studio/mockups/'+(VEHICLES[design.productId]?.name||'van')+(design.options.vehicleColour==='black'?'-black':'')+'.png';
const vehiclePhoto=id=>'/studio/mockups/'+VEHICLES[id].name+'.png';
export function vehicleBox(product){const [x,y,w]=VEHICLES[product.id].box,v=product.views[0];return [x,y,w,w*v.height/v.width];}
const P=(pts,w,h)=>'M'+pts.map(([x,y])=>`${(x*w).toFixed(2)} ${(y*h).toFixed(2)}`).join('L')+'Z';
const R=(x0,y0,x1,y1,w,h,r=0,fill='',extra='')=>`<rect x="${x0*w}" y="${y0*h}" width="${(x1-x0)*w}" height="${(y1-y0)*h}" rx="${r}" fill="${fill}" ${extra}/>`;
function topRounded(x0,y0,x1,y1,r){return `M${x0} ${y1}V${y0+r}Q${x0} ${y0} ${x0+r} ${y0}H${x1-r}Q${x1} ${y0} ${x1} ${y0+r}V${y1}Z`;}
// Vector drawing of rear / front / top views in inch units (w × h). Returns body outline and detail markup.
function vehicleVector(kind,view,w,h){const glass='#2b3440',dark='#24272c',light='#e9eef3',red='#c8262f',chrome='#aeb4bb';let body,details='';
 if(view==='rear'){if(kind==='pickup'){body=`M${w*.01} ${h*.03}H${w*.99}V${h*.79}H${w*.01}Z`;details=R(.44,.1,.56,.22,w,h,.6,dark)+R(0,.02,.055,.72,w,h,.5,red)+R(.945,.02,1,.72,w,h,.5,red)+R(0,.8,1,.97,w,h,1,chrome)+R(.42,.82,.58,.95,w,h,.4,light,`stroke="${dark}" stroke-width=".25"`)+`<path d="M${w*.04} ${h*.3}H${w*.96}" stroke="#00000022" stroke-width=".3"/>`;}
  else{const van=kind==='van',r=w*(van?.12:.24);body=topRounded(w*.02,h*.02,w*.98,h*.82,r);details=(van?R(.09,.1,.47,.38,w,h,1.6,glass)+R(.53,.1,.91,.38,w,h,1.6,glass)+`<path d="M${w*.5} ${h*.05}V${h*.8}" stroke="#00000055" stroke-width=".35"/>`+R(.44,.47,.48,.5,w,h,.3,dark):R(.12,.1,.88,.42,w,h,3,glass)+R(.42,.5,.58,.53,w,h,.4,chrome))+R(.02,.2,.075,van?.62:.46,w,h,.6,red)+R(.925,.2,.98,van?.62:.46,w,h,.6,red)+R(.02,.8,.98,.92,w,h,1.2,dark)+R(.41,van?.66:.58,.59,van?.77:.7,w,h,.4,light,`stroke="${dark}" stroke-width=".25"`)+R(.1,.92,.27,1,w,h,1,'#16181b')+R(.73,.92,.9,1,w,h,1,'#16181b');}}
 else if(view==='front'){body=P([[.1,.02],[.9,.02],[.98,.42],[.98,.82],[.02,.82],[.02,.42]],w,h);const pick=kind==='pickup';details=`<path d="${P([[.1,.02],[.9,.02],[.97,.4],[.03,.4]],w,h)}" fill="#ffffff22" stroke="#00000022" stroke-width=".3"/>`+`<path d="M${w*.36} ${h*.06}L${w*.33} ${h*.38}M${w*.64} ${h*.06}L${w*.67} ${h*.38}" stroke="#00000020" stroke-width=".35"/>`+(pick?R(.24,.45,.76,.76,w,h,1.4,'#30343a',`stroke="${chrome}" stroke-width=".9"`):kind==='van'?R(.3,.5,.7,.7,w,h,1.6,'#2c3036'):R(.35,.52,.65,.62,w,h,1.6,'#2c3036')+R(.3,.68,.7,.76,w,h,1,'#2c3036'))+R(.05,.46,.24,.58,w,h,1.2,'#dfe8f2',`stroke="${chrome}" stroke-width=".4"`)+R(.76,.46,.95,.58,w,h,1.2,'#dfe8f2',`stroke="${chrome}" stroke-width=".4"`)+R(.03,.8,.97,.92,w,h,1.2,pick?chrome:dark)+R(.1,.92,.24,1,w,h,1,'#16181b')+R(.76,.92,.9,1,w,h,1,'#16181b');}
 else{const r=h*.16;body=`M${w*.1} ${h*.05}H${w*.99-r}Q${w*.99} ${h*.05} ${w*.99} ${h*.05+r}V${h*.95-r}Q${w*.99} ${h*.95} ${w*.99-r} ${h*.95}H${w*.1}Q${w*.005} ${h*.95} ${w*.005} ${h*.7}V${h*.3}Q${w*.005} ${h*.05} ${w*.1} ${h*.05}Z`;const ws=kind==='van'?[.07,.15]:kind==='pickup'?[.28,.37]:[.2,.32];details=`<path d="${P([[ws[0],.18],[ws[1],.1],[ws[1],.9],[ws[0],.82]],w,h)}" fill="${glass}"/>`+R(ws[1]-.015,0,ws[1]+.02,.06,w,h,.5,dark)+R(ws[1]-.015,.94,ws[1]+.02,1,w,h,.5,dark);
  if(kind==='van')details+=[.3,.45,.6,.75,.9].map(x=>`<path d="M${w*x} ${h*.12}V${h*.88}" stroke="#00000018" stroke-width=".5"/>`).join('');
  if(kind==='minivan')details+=`<path d="M${w*.36} ${h*.2}H${w*.9}M${w*.36} ${h*.8}H${w*.9}" stroke="${chrome}" stroke-width=".9"/>`+`<path d="${P([[.92,.16],[.97,.2],[.97,.8],[.92,.84]],w,h)}" fill="${glass}"/>`;
  if(kind==='pickup')details+=`<path d="${P([[.58,.12],[.61,.12],[.61,.88],[.58,.88]],w,h)}" fill="${glass}"/>`+R(.65,.12,.975,.88,w,h,1,'#3a3f47',`stroke="${chrome}" stroke-width=".6"`)+[.72,.79,.86,.93].map(x=>`<path d="M${w*x} ${h*.14}V${h*.86}" stroke="#ffffff14" stroke-width=".6"/>`).join('')+`<path d="M${w*.04} ${h*.35}L${w*.27} ${h*.33}M${w*.04} ${h*.65}L${w*.27} ${h*.67}" stroke="#00000018" stroke-width=".4"/>`;}
 return {body,details};}
const viewKey=(product,side)=>product.views?.[side]?.key;
// Guide overlay added on top of the editor canvas (W × H in canvas units = inches × 100).
export function stageOverlay(product,design,side,W,H){
 if(product.views&&VEHICLES[product.id]){const key=viewKey(product,side);if(key==='driver-side'||key==='passenger-side'){const [bx,by,bw]=vehicleBox(product),k=W/bw,name=VEHICLES[product.id].name,img=`<image href="/studio/mockups/${name}.png" x="${-bx*k}" y="${-by*k}" width="${1536*k}" height="${1024*k}" style="mix-blend-mode:multiply" opacity=".92"/><image href="/studio/mockups/${name}-veil.webp" x="${-bx*k}" y="${-by*k}" width="${1536*k}" height="${1024*k}"/>`;return `<g pointer-events="none" ${key==='passenger-side'?`transform="matrix(-1 0 0 1 ${W} 0)"`:''}>${img}</g>`;}
  const v=vehicleVector(VEHICLES[product.id].name,key==='rear'?'rear':key==='front'?'front':'top',W/100,H/100);return `<g pointer-events="none" transform="scale(100)"><path d="M-5 -5H${W/100+5}V${H/100+5}H-5Z ${v.body}" fill="#f4f5f7" fill-opacity=".82" fill-rule="evenodd"/><g opacity=".55">${v.details}</g><path d="${v.body}" fill="none" stroke="#6b7686" stroke-width="${W/100/260}" stroke-dasharray="${W/100/90} ${W/100/140}"/></g>`;}
 if(product.hole){const o=hangerHole(W,H);return `<g pointer-events="none"><circle cx="${o.cx}" cy="${o.cy}" r="${o.r}" fill="#e7e9ee" stroke="#8a99ae" stroke-width="${W/300}" stroke-dasharray="${W/60} ${W/90}"/><path d="M${o.slit[0].join(' ')}L${o.slit[1].join(' ')}" stroke="#8a99ae" stroke-width="${W/220}" stroke-dasharray="${W/60} ${W/120}"/></g>`;}
 return '';}
async function vectorView(kind,view,w,h,art,colour){const v=vehicleVector(kind,view,w,h),href=art.toDataURL('image/png');const paint=colour==='black'?'#1d1f23':'#f7f8fa';const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="-1 -1 ${w+2} ${h+2}" width="${(w+2)*12}" height="${(h+2)*12}"><defs><clipPath id="b"><path d="${v.body}"/></clipPath><linearGradient id="s" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity=".35"/><stop offset=".45" stop-color="#fff" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".22"/></linearGradient><linearGradient id="g" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#000" stop-opacity=".16"/><stop offset=".18" stop-color="#000" stop-opacity="0"/><stop offset=".82" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".16"/></linearGradient></defs><path d="${v.body}" fill="${paint}"/><image href="${href}" x="0" y="0" width="${w}" height="${h}" preserveAspectRatio="none" clip-path="url(#b)"/><path d="${v.body}" fill="url(#s)"/><path d="${v.body}" fill="url(#g)"/>${v.details}<path d="${v.body}" fill="none" stroke="#00000040" stroke-width="${w/400}"/></svg>`;return load('data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg));}
async function photoSide(product,art,mirrored){const name=VEHICLES[product.id].name,[photo,mask]=await Promise.all([load(vehiclePhoto(product.id)),load(`/studio/mockups/${name}-mask.webp`)]);const [bx,by,bw,bh]=vehicleBox(product);const [c,ctx]=canvas(1536,1024);const flip=g=>{if(mirrored){g.translate(1536,0);g.scale(-1,1);}};ctx.save();flip(ctx);ctx.drawImage(photo,0,0);ctx.restore();
 const [o,octx]=canvas(1536,1024);if(mirrored)octx.drawImage(art,1536-bx-bw,by,bw,bh);else octx.drawImage(art,bx,by,bw,bh);octx.globalCompositeOperation='destination-in';octx.save();flip(octx);octx.drawImage(mask,0,0);octx.restore();ctx.globalCompositeOperation='multiply';ctx.drawImage(o,0,0);ctx.globalCompositeOperation='source-over';return c;}
async function vehicleScene(model,arts){const product=PRODUCTS.find(p=>p.id===model.productId),kind=VEHICLES[product.id].name,colour=model.options.vehicleColour;const [c,ctx]=canvas(1800,1320);const bg=ctx.createLinearGradient(0,0,0,1320);bg.addColorStop(0,'#f3f4f6');bg.addColorStop(1,'#dfe2e7');ctx.fillStyle=bg;ctx.fillRect(0,0,1800,1320);
 const label=(text,x,y)=>{ctx.fillStyle='#4b5563';ctx.font='600 26px Inter, Arial, sans-serif';ctx.textAlign='center';ctx.fillText(t(text),x,y);};
 const views=sideViews(product);const sideImg=async i=>photoSide(product,arts[i],i===1);
 for(const i of [0,1]){if(!arts[i])continue;const img=await sideImg(i),crop=[0,140,1536,800],w=860,h=w*crop[3]/crop[2],x=i?900:40;ctx.drawImage(img,crop[0],crop[1],crop[2],crop[3],x,30,w,h);label(views[i].label,x+w/2,30+h+34);}
 const cells=[[2,'rear'],[3,'front'],[4,'top']].filter(([i])=>arts[i]);let x=60,bottom=560;const widths={2:360,3:360,4:860};for(const [i,view] of cells){const v=views[i],img=await vectorView(kind,view,v.width,v.height,arts[i],colour);const maxW=widths[i]*(cells.length<3?1.25:1),[w,h]=fit(img,maxW,430),cy=600+(560-h)/2;ctx.save();ctx.fillStyle='#0000001c';ctx.filter='blur(14px)';ctx.beginPath();ctx.ellipse(x+w/2,cy+h-6,w*.46,18,0,0,Math.PI*2);ctx.fill();ctx.restore();ctx.drawImage(img,x,cy,w,h);label(v.label,x+w/2,cy+h+48);bottom=Math.max(bottom,cy+h+60);x+=w+60;}
 const H=Math.min(1320,bottom+60),[out,octx]=canvas(1800,H);octx.drawImage(c,0,0);octx.fillStyle='#8a919c';octx.font='20px Inter, Arial, sans-serif';octx.textAlign='right';octx.fillText(t('Illustrative preview · exact vehicle templates are confirmed before production'),1770,H-20);return out.toDataURL('image/png');}

/* ---------------- print scenes ---------------- */
async function tabletop(w,h){const [c,ctx]=canvas(w,h);try{const table=await load('/studio/tabletop.png');const s=Math.max(w/table.width,h/table.height);ctx.drawImage(table,(w-table.width*s)/2,(h-table.height*s)/2,table.width*s,table.height*s);}catch{ctx.fillStyle='#e7e7ea';ctx.fillRect(0,0,w,h);}return [c,ctx];}
function paper(ctx,art,cx,cy,w,h,rot,{radius=0,stack=0,shadow=34,blank=false}={}){ctx.save();ctx.translate(cx,cy);ctx.rotate(rot);for(let i=stack;i>0;i--){ctx.save();ctx.translate(i*1.4,i*2.2);ctx.shadowColor='#0f172a30';ctx.shadowBlur=i===stack?shadow:0;ctx.shadowOffsetY=i===stack?shadow*.5:0;ctx.fillStyle=i%2?'#f2f2f0':'#e6e6e3';rr(ctx,-w/2,-h/2,w,h,radius);ctx.fill();ctx.restore();}ctx.shadowColor='#0f172a3d';ctx.shadowBlur=stack?6:shadow;ctx.shadowOffsetY=stack?3:shadow*.55;ctx.fillStyle='#fff';rr(ctx,-w/2,-h/2,w,h,radius);ctx.fill();ctx.shadowColor='transparent';ctx.save();rr(ctx,-w/2,-h/2,w,h,radius);ctx.clip();if(!blank)ctx.drawImage(art,-w/2,-h/2,w,h);const g=ctx.createLinearGradient(-w/2,-h/2,w/2,h/2);g.addColorStop(0,'#ffffff30');g.addColorStop(.5,'#ffffff00');g.addColorStop(1,'#00000014');ctx.fillStyle=g;ctx.fillRect(-w/2,-h/2,w,h);ctx.restore();ctx.restore();}
async function businessCards(model,arts){const [c,ctx]=await tabletop(1500,1000);const front=arts[0],back=arts[1],rounded=!!model.options.rounded;const [w,h]=fit(front,600,400),radius=rounded?Math.min(w,h)*.06:0;
 paper(ctx,back||front,1030,640,w,h,.1,{radius,stack:6,blank:!back});paper(ctx,front,480,390,w,h,-.09,{radius,stack:9});if(back){}return c.toDataURL('image/png');}
async function sheets(model,arts){const [c,ctx]=await tabletop(1600,1100);const front=arts[0],back=arts[1];if(back){const [w,h]=fit(front,640,860);paper(ctx,front,800-w/2-40,560,w,h,-.035,{stack:3});const [bw,bh]=[w,h];paper(ctx,back,800+bw/2+40,560,bw,bh,.035,{stack:3});}else{const [w,h]=fit(front,900,880);paper(ctx,front,800,550,w,h,-.03,{stack:5});}
 if(back){ctx.fillStyle='#ffffffd9';ctx.font='600 24px Inter, Arial, sans-serif';ctx.textAlign='center';}return c.toDataURL('image/png');}
async function brochure(model,arts){const [c,ctx]=await tabletop(1400,1000);const n=model.options.fold==='Half-fold'?2:3;const draw=(image,x,y,maxW,maxH,rotation)=>{const aspect=image.width/image.height,w=Math.min(maxW,maxH*aspect),h=w/aspect,panel=w/n,slopes=n===2?[.12,-.08]:model.options.fold==='Z-fold'?[.12,-.14,.12]:[.1,0,-.12],factors=n===2?[.85,1]:[.85,.8,.85],total=panel*factors.reduce((a,b)=>a+b,0);ctx.save();ctx.translate(x,y);ctx.rotate(rotation);let left=-total/2;for(let i=0;i<n;i++){const width=panel*factors[i];ctx.save();ctx.translate(left,-h/2);ctx.transform(1,slopes[i],0,1,0,0);ctx.shadowColor='#16233333';ctx.shadowBlur=18;ctx.shadowOffsetY=13;ctx.fillStyle='white';ctx.fillRect(0,0,width,h);ctx.shadowColor='transparent';ctx.drawImage(image,i*image.width/n,0,image.width/n,image.height,0,0,width,h);const g=ctx.createLinearGradient(0,0,width,0);g.addColorStop(0,'#00000018');g.addColorStop(.45,'#ffffff00');g.addColorStop(1,'#00000020');ctx.fillStyle=g;ctx.fillRect(0,0,width,h);ctx.restore();left+=width;}ctx.restore();};draw(arts[0],450,390,690,540,-.08);if(arts[1])draw(arts[1],960,650,520,430,.06);return c.toDataURL('image/png');}
async function flatGeneric(model,arts){const [c,ctx]=await tabletop(1400,1000);if(arts[1]){const [w,h]=fit(arts[0],560,800);paper(ctx,arts[0],700-w/2-30,500,w,h,-.03);paper(ctx,arts[1],700+w/2+30,500,w,h,.03);}else{const [w,h]=fit(arts[0],1050,820);paper(ctx,arts[0],700,490,w,h,-.04);}return c.toDataURL('image/png');}
// Door hangers hung on two door knobs: front on the left door, back on the right.
async function doorHangers(model,arts){const [c,ctx]=canvas(1600,1200);const product=PRODUCTS.find(p=>p.id===model.productId),d=dimensions(product,model.options);
 for(const [i,art] of [[0,arts[0]],[1,arts[1]]]){const ox=i*800;ctx.save();ctx.beginPath();ctx.rect(ox,0,800,1200);ctx.clip();
  const wall=ctx.createLinearGradient(ox,0,ox+800,0);wall.addColorStop(0,'#e9e4dc');wall.addColorStop(1,'#ddd6cc');ctx.fillStyle=wall;ctx.fillRect(ox,0,800,1200);
  // door leaf with casing and raised panels
  const dx=ox+(i?40:120),dw=640;ctx.fillStyle='#f6f3ee';ctx.fillRect(dx-34,0,dw+68,1200);ctx.fillStyle='#00000012';ctx.fillRect(dx-6,0,6,1200);const door=ctx.createLinearGradient(dx,0,dx+dw,0);door.addColorStop(0,'#2d4157');door.addColorStop(.55,'#34495f');door.addColorStop(1,'#2a3c50');ctx.fillStyle=door;ctx.fillRect(dx,0,dw,1200);
  for(const [px,py,pw,ph] of [[dx+70,-60,dw-140,420],[dx+70,560,dw-140,700]]){ctx.strokeStyle='#ffffff1f';ctx.lineWidth=3;ctx.strokeRect(px,py,pw,ph);ctx.strokeStyle='#00000035';ctx.strokeRect(px+8,py+8,pw-16,ph-16);}
  const kx=i?dx+dw-200:dx+200,ky=430;ctx.fillStyle='#00000030';ctx.beginPath();ctx.ellipse(kx+6,ky+8,46,46,0,0,Math.PI*2);ctx.fill();const rose=ctx.createRadialGradient(kx-12,ky-14,4,kx,ky,44);rose.addColorStop(0,'#f4f5f7');rose.addColorStop(1,'#8d939b');ctx.fillStyle=rose;ctx.beginPath();ctx.arc(kx,ky,42,0,Math.PI*2);ctx.fill();
  // hanger geometry (scaled so it hangs to roughly 2/3 of the panel)
  const k=Math.min(760/d.height,300/d.width),w=d.width*k,h=d.height*k,hole=hangerHole(d.width*100,d.height*100),s=k/100,neck=14,hy=ky-neck+hole.r*s-hole.cy*s,hx=kx-w/2,rot=i?.022:-.018;
  ctx.save();ctx.translate(kx,ky);ctx.rotate(rot);ctx.translate(-kx,-ky);const shape=()=>{ctx.beginPath();ctx.roundRect(hx,hy,w,h,Math.min(w,h)*.035);ctx.moveTo(hx+hole.cx*s+hole.r*s,hy+hole.cy*s);ctx.arc(hx+hole.cx*s,hy+hole.cy*s,hole.r*s,0,Math.PI*2,true);};
  ctx.save();ctx.shadowColor='#00000055';ctx.shadowBlur=26;ctx.shadowOffsetX=12;ctx.shadowOffsetY=16;ctx.fillStyle='#fff';shape();ctx.fill('evenodd');ctx.restore();ctx.save();shape();ctx.clip('evenodd');ctx.drawImage(art||arts[0],hx,hy,w,h);if(!art){ctx.fillStyle='#fff';ctx.fillRect(hx,hy,w,h);}const g=ctx.createLinearGradient(hx,0,hx+w,0);g.addColorStop(0,'#00000010');g.addColorStop(.5,'#ffffff18');g.addColorStop(1,'#00000016');ctx.fillStyle=g;ctx.fillRect(hx,hy,w,h);ctx.restore();
  ctx.strokeStyle='#33415555';ctx.lineWidth=2.2;ctx.beginPath();ctx.moveTo(hx+hole.slit[0][0]*s,hy+hole.slit[0][1]*s);ctx.lineTo(hx+hole.slit[1][0]*s,hy+hole.slit[1][1]*s);ctx.stroke();ctx.restore();
  // knob sits in front of the hanger, covering the hole
  ctx.fillStyle='#0000004d';ctx.filter='blur(6px)';ctx.beginPath();ctx.arc(kx+8,ky+12,hole.r*s*.8,0,Math.PI*2);ctx.fill();ctx.filter='none';const knob=ctx.createRadialGradient(kx-hole.r*s*.3,ky-hole.r*s*.35,3,kx,ky,hole.r*s*.85);knob.addColorStop(0,'#ffffff');knob.addColorStop(.35,'#d5d9de');knob.addColorStop(1,'#6f7780');ctx.fillStyle=knob;ctx.beginPath();ctx.arc(kx,ky,hole.r*s*.82,0,Math.PI*2);ctx.fill();
  ctx.fillStyle='#ffffffe6';ctx.font='600 24px Inter, Arial, sans-serif';ctx.textAlign='center';ctx.fillText(t(i?'Back':'Front'),dx+dw/2,1160);ctx.restore();}
 return c.toDataURL('image/png');}
// Yard sign on an H-wire stake in a lawn.
async function yardSigns(model,arts){const W=1600,H=1100,[c,ctx]=canvas(W,H),rand=rng(11);const sky=ctx.createLinearGradient(0,0,0,560);sky.addColorStop(0,'#bcd8ee');sky.addColorStop(1,'#eef4f6');ctx.fillStyle=sky;ctx.fillRect(0,0,W,560);
 ctx.save();ctx.filter='blur(10px)';for(let i=0;i<26;i++){ctx.fillStyle=['#5d7f4a','#4f7140','#6c8d52','#46663a'][i%4];ctx.beginPath();ctx.ellipse(i*66-20,520-rand()*60,80+rand()*50,70+rand()*50,0,0,Math.PI*2);ctx.fill();}ctx.fillStyle='#d9d3c7';ctx.fillRect(0,540,W,26);ctx.restore();
 const lawn=ctx.createLinearGradient(0,560,0,H);lawn.addColorStop(0,'#7da552');lawn.addColorStop(1,'#4d7d2e');ctx.fillStyle=lawn;ctx.fillRect(0,560,W,H-560);for(let i=0;i<2600;i++){const y=560+Math.pow(rand(),.7)*(H-560),x=rand()*W,l=4+(y-560)/26*rand();ctx.strokeStyle=rand()>.5?'#3f6d24aa':'#9cc46aa0';ctx.lineWidth=1+(y-560)/300;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+(rand()-.5)*6,y-l);ctx.stroke();}
 const signs=arts[1]?[[arts[0],470,560,.98,'Front'],[arts[1],1150,520,.86,'Back']]:[[arts[0],800,600,1.25,null]];
 for(const [art,cx,w0,scale,label] of signs){const [w,h]=fit(art,w0*scale,w0*scale*.85),top=1010-(scale*330)-h,bottom=top+h,stakes=[cx-w*.3,cx+w*.3],ground=bottom+scale*300;
  ctx.save();ctx.fillStyle='#1f3a1255';ctx.filter='blur(16px)';ctx.beginPath();ctx.ellipse(cx+40,ground+6,w*.55,26*scale,0,0,Math.PI*2);ctx.fill();ctx.restore();
  ctx.strokeStyle='#3d4247';ctx.lineWidth=5*scale;ctx.lineCap='round';for(const x of stakes){ctx.beginPath();ctx.moveTo(x,bottom-h*.25);ctx.lineTo(x,ground);ctx.stroke();}for(const y of [bottom+70*scale,bottom+150*scale]){ctx.beginPath();ctx.moveTo(stakes[0],y);ctx.lineTo(stakes[1],y);ctx.stroke();}ctx.strokeStyle='#ffffff40';ctx.lineWidth=1.5*scale;for(const x of stakes){ctx.beginPath();ctx.moveTo(x-1.5*scale,bottom);ctx.lineTo(x-1.5*scale,ground);ctx.stroke();}
  ctx.save();ctx.shadowColor='#0000004a';ctx.shadowBlur=24;ctx.shadowOffsetX=14;ctx.shadowOffsetY=12;ctx.fillStyle='#e9ecef';ctx.fillRect(cx-w/2+4,top+4,w,h);ctx.restore();ctx.fillStyle='#c9ced4';ctx.fillRect(cx-w/2+5,top+5,w,h);ctx.drawImage(art,cx-w/2,top,w,h);const g=ctx.createLinearGradient(cx-w/2,top,cx+w/2,bottom);g.addColorStop(0,'#ffffff2e');g.addColorStop(.4,'#ffffff00');g.addColorStop(1,'#00000018');ctx.fillStyle=g;ctx.fillRect(cx-w/2,top,w,h);
  for(let i=0;i<140;i++){const x=cx-w*.45+rand()*w*.9,y=ground-6+rand()*18,l=10+rand()*22*scale;ctx.strokeStyle=rand()>.4?'#3f6d24':'#8db85c';ctx.lineWidth=1.6*scale;ctx.beginPath();ctx.moveTo(x,y);ctx.quadraticCurveTo(x+(rand()-.5)*8,y-l*.6,x+(rand()-.5)*10,y-l);ctx.stroke();}
  if(label){ctx.fillStyle='#ffffffe0';ctx.font='600 26px Inter, Arial, sans-serif';ctx.textAlign='center';ctx.fillText(t(label),cx,H-28);}}
 return c.toDataURL('image/png');}
// Roll-up banner on a retractable stand in a softly lit room.
async function rollUp(model,arts){const W=1400,H=1100,[c,ctx]=canvas(W,H);const wall=ctx.createLinearGradient(0,0,0,860);wall.addColorStop(0,'#eef0f3');wall.addColorStop(1,'#dfe2e7');ctx.fillStyle=wall;ctx.fillRect(0,0,W,860);for(const x of [260,700,1140]){const l=ctx.createRadialGradient(x,0,10,x,120,420);l.addColorStop(0,'#ffffffcc');l.addColorStop(1,'#ffffff00');ctx.fillStyle=l;ctx.fillRect(x-420,0,840,700);}const floor=ctx.createLinearGradient(0,860,0,H);floor.addColorStop(0,'#c9cdd3');floor.addColorStop(1,'#b3b8bf');ctx.fillStyle=floor;ctx.fillRect(0,860,W,H-860);ctx.fillStyle='#ffffff80';ctx.fillRect(0,858,W,3);
 const art=arts[0],[w,h]=fit(art,700,840),x=(W-w)/2,y=960-h-46;ctx.save();ctx.fillStyle='#0000002e';ctx.filter='blur(18px)';ctx.beginPath();ctx.ellipse(W/2,978,w*.62,26,0,0,Math.PI*2);ctx.fill();ctx.restore();ctx.fillStyle='#00000014';ctx.filter='blur(22px)';ctx.fillRect(x+30,y+20,w,h);ctx.filter='none';
 ctx.drawImage(art,x,y,w,h);const g=ctx.createLinearGradient(x,0,x+w,0);g.addColorStop(0,'#00000018');g.addColorStop(.12,'#ffffff12');g.addColorStop(.5,'#ffffff00');g.addColorStop(.88,'#ffffff10');g.addColorStop(1,'#00000020');ctx.fillStyle=g;ctx.fillRect(x,y,w,h);
 const metal=(y0,hgt)=>{const m=ctx.createLinearGradient(0,y0,0,y0+hgt);m.addColorStop(0,'#f5f6f7');m.addColorStop(.5,'#b9bec4');m.addColorStop(1,'#80868e');return m;};ctx.fillStyle=metal(y-10,14);rr(ctx,x-6,y-10,w+12,14,4);ctx.fill();ctx.fillStyle='#5b6169';ctx.fillRect(x-10,y-12,6,18);ctx.fillRect(x+w+4,y-12,6,18);
 ctx.fillStyle=metal(y+h-4,48);rr(ctx,x-24,y+h-4,w+48,48,10);ctx.fill();ctx.fillStyle='#00000026';ctx.fillRect(x-20,y+h+28,w+40,3);ctx.fillStyle='#6a7078';for(const fx of [x-30,x+w-50]){rr(ctx,fx,y+h+38,80,10,4);ctx.fill();}
 return c.toDataURL('image/png');}

/* ---------------- apparel ---------------- */
// Printable area on the garment photo (fractions of the square photo) per side key.
export function printArea(product,key){const g=product.garment||{},cat=g.category||'',women=g.group==='women',youth=g.group==='youth';if(g.group==='hats')return {x:.35,y:.29,w:.3};if(g.group==='totes')return {x:.32,y:.45,w:.36};if(key==='left-sleeve')return {x:.668,y:.3,w:.066};if(key==='right-sleeve')return {x:.266,y:.3,w:.066};const w=cat==='hoodies'?.24:women?.25:youth?.26:.29;if(key==='back')return {x:.5-w/2-.005,y:cat==='hoodies'?.3:.22,w};return {x:.5-w/2,y:cat==='hoodies'?.24:.28,w};}
export async function apparelScene(model,arts,photoFor,background='#f1f2f4'){const product=PRODUCTS.find(p=>p.id===model.productId),views=sideViews(product),hasBack=views.some(v=>v.key==='back');const panels=hasBack?['front','back']:['front'];const S=900,gap=40,W=panels.length*S+(panels.length+1)*gap,H=S+gap*2;const [c,ctx]=canvas(W,H);ctx.fillStyle=background;ctx.fillRect(0,0,W,H);
 for(const [p,key] of panels.entries()){const x=gap+p*(S+gap),y=gap;const photo=await load(photoFor(key));ctx.save();ctx.shadowColor='#0f172a22';ctx.shadowBlur=30;ctx.shadowOffsetY=12;ctx.fillStyle='#fff';rr(ctx,x,y,S,S,22);ctx.fill();ctx.restore();ctx.save();rr(ctx,x,y,S,S,22);ctx.clip();ctx.drawImage(photo,x,y,S,S);
  for(const [i,v] of views.entries()){if(!arts[i])continue;const onThis=key==='front'?v.key!=='back':v.key==='back';if(!onThis)continue;const a=printArea(product,v.key),d=dimensions(product,model.options,i),aw=a.w*S,ah=aw*d.height/d.width;ctx.globalAlpha=.96;ctx.drawImage(arts[i],x+a.x*S,y+a.y*S,aw,ah);ctx.globalAlpha=1;}
  ctx.restore();ctx.fillStyle=background==='#22252b'?'#ffffffcc':'#4b5563';ctx.font='600 26px Inter, Arial, sans-serif';ctx.textAlign='center';}
 return c.toDataURL('image/png');}

/* ---------------- photographed displays (x-frame, a-frame, flags) ---------------- */
function quad(ctx,art,points){const [a,b,c,d]=points;for(let y=0;y<art.height;y++){const t=y/art.height,t2=(y+1)/art.height,l=[a[0]+(d[0]-a[0])*t,a[1]+(d[1]-a[1])*t],r=[b[0]+(c[0]-b[0])*t,b[1]+(c[1]-b[1])*t],l2=[a[0]+(d[0]-a[0])*t2,a[1]+(d[1]-a[1])*t2];ctx.save();ctx.setTransform((r[0]-l[0])/art.width,(r[1]-l[1])/art.width,l2[0]-l[0],l2[1]-l[1],l[0],l[1]);ctx.drawImage(art,0,y,art.width,1,0,0,art.width,1.5);ctx.restore();}}
async function photoScene(id,first,second){let photo,box,quads;if(id==='a-frame-signs'){photo='/studio/mockups/aframe.png';box=[530,144,472,628];}else if(id==='x-frame-banner'){photo='/satin/img/pr-xframe-960.webp';quads=[[[175,43],[451,37],[437,819],[153,810]],[[573,88],[807,92],[827,740],[588,748]]];}else photo='/satin/img/pr-flags-row-480.webp';
 const image=await load(photo),[c,ctx]=canvas(image.width,image.height);ctx.drawImage(image,0,0);if(quads)quads.forEach((q,i)=>quad(ctx,i===1&&second?second:first,q));
 else if(id==='flags'){for(const dx of [0,137,271]){ctx.save();ctx.beginPath();ctx.moveTo(70+dx,365);ctx.lineTo(70+dx,142);ctx.bezierCurveTo(70+dx,91,95+dx,55,126+dx,56);ctx.bezierCurveTo(157+dx,55,168+dx,73,168+dx,93);ctx.bezierCurveTo(155+dx,154,102+dx,294,70+dx,365);ctx.closePath();ctx.clip();ctx.drawImage(first,69+dx,55,100,314);const shade=ctx.createLinearGradient(69+dx,0,169+dx,0);shade.addColorStop(0,'#0003');shade.addColorStop(.3,'#fff2');shade.addColorStop(.6,'#0001');shade.addColorStop(1,'#fff2');ctx.fillStyle=shade;ctx.fillRect(69+dx,55,100,314);ctx.restore();}}
 else{ctx.save();ctx.beginPath();ctx.rect(...box);ctx.clip();ctx.drawImage(first,...box);ctx.restore();}return c.toDataURL('image/png');}

// arts: array indexed by side (canvas or null). Returns a PNG data URL.
export async function renderMockup(model,arts,options={}){const id=model.productId;if(id.startsWith('vehicle-'))return vehicleScene(model,arts);if(id.startsWith('apparel-'))return apparelScene(model,arts,options.photoFor,options.background);
 if(id==='business-cards')return businessCards(model,arts);if(id==='flyers'||id==='postcards')return sheets(model,arts);if(id==='brochures')return brochure(model,arts);if(id==='door-hangers')return doorHangers(model,arts);if(id==='yard-signs')return yardSigns(model,arts);if(id==='roll-up-banner')return rollUp(model,arts);
 if(['a-frame-signs','x-frame-banner','flags'].includes(id))return photoScene(id,arts[0],arts[1]);return flatGeneric(model,arts);}
